        static void AddText(string packed) { Add(Texts, packed); }
        static void AddCanonical(string packed) { Add(CanonicalValues, packed); }

        static void Add(Dictionary<string, string[]> target, string packed)
        {
            string[] values = packed.Split('|');
            if (values.Length == 18) { Array.Resize(ref values, 19); values[18] = UiLanguage.ToTraditional(values[0]); }
            if (values.Length != 19)
                throw new InvalidOperationException("Project-creation language vocabulary must contain 19 values: " + values[0]);
            target[values[0]] = values;
            target[values[1]] = values;
        }

        internal static void Validate(int value)
        {
            if (value < -1 || value >= Names.Length)
                throw new ArgumentOutOfRangeException("LanguageIndex", "Expected -1 (system) or 0..18.");
        }

        internal static int FindCode(string code)
        { return Xiongxin.OWTS.Localization.UiLanguage.FindCode(code); }

        internal static string Text(int language, string chinese, string english)
        {
            Validate(language);
            language = UiLanguage.ResolveIndex(language);
            if (language == 0) return chinese ?? String.Empty;
            if (language == 18) return UiLanguage.ToTraditional(chinese ?? String.Empty);
            string localized; if (UiLanguage.TryTranslate(language, english, out localized)) return localized;
            language = UiLanguage.LegacyIndex(language);
            if (language == 1) return UiLanguage.Translate(language, english) ?? String.Empty;
            string[] values;
            if (!String.IsNullOrEmpty(chinese) && Texts.TryGetValue(chinese, out values)) return values[language];
            if (!String.IsNullOrEmpty(english) && Texts.TryGetValue(english, out values)) return values[language];
            return english ?? chinese ?? String.Empty;
        }

        internal static string Canonical(int language, string canonical, string english)
        {
            Validate(language);
            language = UiLanguage.ResolveIndex(language);
            if (language == 0) return canonical ?? String.Empty;
            string localized; if (language != 18 && UiLanguage.TryTranslate(language, english, out localized)) return localized;
            language = UiLanguage.LegacyIndex(language);
            string[] values;
            if (!String.IsNullOrEmpty(canonical) && CanonicalValues.TryGetValue(canonical, out values))
                return values[language];
            if (!String.IsNullOrEmpty(english) && CanonicalValues.TryGetValue(english, out values))
                return values[language];
            // Unknown canonical values may be customer-entered catalog entries.
            // Never script-convert them while translating predefined choices.
            return language == 18 ? canonical ?? String.Empty : english ?? canonical ?? String.Empty;
        }
    }

    public partial class ProjectCreationControl
    {
        [Browsable(false)]
        public string[] AvailableLanguages { get { return (string[])ProjectCreationLanguageContract.Names.Clone(); } }

        public string[] GetLanguageNames() { return (string[])ProjectCreationLanguageContract.Names.Clone(); }
        public string[] GetLanguageCodes() { return (string[])ProjectCreationLanguageContract.Codes.Clone(); }

        public bool SetLanguageCode(string code)
        {
            if (String.Equals(code, "system", StringComparison.OrdinalIgnoreCase)) { SetLanguageIndex(-1); return true; }
            int index = ProjectCreationLanguageContract.FindCode(code);
            if (index < 0) return false;
            SetLanguageIndex(index);
            return true;
        }
    }
